from __future__ import annotations

__doc__ = """Summand objects that combine bases, coefficients, and modifiers."""

import warnings
from .scalar import Scalar
from .modifier import _Modifier


class Summand:
    """
    Summand class
    """

    CLS_MODIFIER = Scalar

    def __init__(self, bases: tuple, comps: tuple, modif=None):
        self._comps = comps
        self._bases = bases
        modif = self.__class__.CLS_MODIFIER.to_modifier(modif)
        self._modif = modif

    @classmethod
    def set_modifier(cls, modif_class, /):
        """set the modifier of the class"""
        if not isinstance(modif_class, type):
            raise TypeError("modifier class must be of type class")
        if not issubclass(modif_class, _Modifier):
            raise TypeError("modifier class must be subclass of '_Modifier'")
        warnings.warn("Modifier class has changed!")
        cls.CLS_MODIFIER = modif_class

    @property
    def comps(self):
        """access read-only attribute components"""
        return self._comps

    @property
    def bases(self):
        """access read-only attribute bases"""
        return self._bases

    @property
    def coeff(self):
        """access read-only attribute coefficient/prefix"""
        return self._modif

    @property
    def prefix(self):
        """access read-only attribute prefix"""
        return self._modif

    @property
    def modifier(self):
        """access read-only attribute modifier"""
        return self._modif

    def copy(self):
        """copy a summand"""
        return Summand(self._bases, self._comps, self._modif)


print("foo")
Summand.set_modifier(Scalar)
print("bar")
